package communicationcontrol

import (
	"encoding/json"
	"os"
	"testing"
)

// This is the frozen C01 shape corpus, not a channel renderer or live delivery.
// Native expectations are independently written, not generated by product code.
func TestCommunicationV1FormatAndNativeRichMessageCorpus(t *testing.T) {
	raw, e := os.ReadFile("testdata/v1.json")
	if e != nil {
		t.Fatal(e)
	}
	var corpus struct {
		Schema   int    `json:"schema_version"`
		Telegram string `json:"telegram_contract"`
		Fixtures []struct {
			Name, Tool string
			Args       json.RawMessage
			Answer     *Answer
			Native     *struct {
				Method      string `json:"method"`
				RichMessage struct {
					Blocks []map[string]json.RawMessage `json:"blocks"`
				} `json:"rich_message"`
			}
		}
	}
	if e = json.Unmarshal(raw, &corpus); e != nil || corpus.Schema != 1 || len(corpus.Fixtures) != 6 {
		t.Fatal(e)
	}
	seen := map[string]bool{}
	for _, f := range corpus.Fixtures {
		t.Run(f.Name, func(t *testing.T) {
			a, e := DecodeArgs(f.Tool, string(f.Args))
			if e != nil {
				t.Fatal(e)
			}
			seen[f.Tool] = true
			if f.Answer != nil && (a.Input == nil || ValidateAnswer(*a.Input, *f.Answer) != nil) {
				t.Fatal("response shape differs from question")
			}
			if f.Name == "report" {
				if f.Native == nil || f.Native.Method != "sendRichMessage" || len(f.Native.RichMessage.Blocks) != 9 {
					t.Fatal("native report replaced by link or summary")
				}
				want := []string{"heading", "paragraph", "list", "blockquote", "pre", "table", "divider", "photo", "document"}
				for i, b := range f.Native.RichMessage.Blocks {
					var typ string
					if json.Unmarshal(b["type"], &typ) != nil || typ != want[i] {
						t.Fatal("native block mismatch", i)
					}
					if typ == "photo" || typ == "document" {
						var media struct{ Type, Media string }
						if json.Unmarshal(b[typ], &media) != nil || media.Type != typ || media.Media != "attach://"+map[string]string{"photo": "image", "document": "document"}[typ] {
							t.Fatal("native media requires private multipart, not public URL")
						}
					}
				}
			}
		})
	}
	if len(seen) != 4 {
		t.Fatal("four model formats not frozen")
	}
}
